If $p=n^{-a}$ with $0<a\le \frac{2}{3}$ and  $d=\left[ \frac{2}{a} \right]$, when $N_{\mathsf{e}}=o\left( \frac{\log n}{\max\left( \log\log n,-\log\rho \right)} \right)$ and $N_{\mathsf{e}}\ge \frac{C_1(d)}{\rho^{2d/(d-2)}}$ for some constant $C_1(d)$ depending on $d$,\begin{align*}
        \mathcal{P}_0\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\ge \tau \right)+\mathcal{P}_1\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}<\tau \right)\le 0.05.
    \end{align*}

    If $p=n^{-o(1)}$, then for any constant $\epsilon>0$, when $N_{\mathsf{e}} = o\left( \frac{\log n}{\max\left( \log\log n,-\log\rho \right)} \right)$ and $N_{\mathsf{e}}\ge \frac{C_2(\epsilon)}{\rho^{2+\epsilon}}$ for some constant $C_2(\epsilon)$ depending on $\epsilon$,\begin{align*}
        \mathcal{P}_0\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}\ge \tau \right)+\mathcal{P}_1\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}<\tau \right)\le 0.05.
    \end{align*}

    Furthermore, $\mathcal{T}_{\mathcal{M}(N_{\mathsf{v}},N_{\mathsf{e}},d)}$ is  computable in $O(n^{N_{\mathsf{e}}})$.

If $p=n^{-a}$ with constant $0<a< \frac{2}{3}$, then for $d=3\cdot {\mathbf{1}_{\left\{{\frac{2}{5}<a<\frac{2}{3}}\right\}}}+\left( \left[ \frac{2}{a} \right]-1 \right)\cdot {\mathbf{1}_{\left\{{0<a\le \frac{2}{5}}\right\}}}$, when $N_{\mathsf{e}}=o\left( \frac{\log n}{\max\left( \log\log n,-\log\rho \right)} \right)$ and $N_{\mathsf{e}}\ge \frac{C_1(d)}{\rho^{2d/(d-2)}}$ for some constant $C_1(d)$ depending on $d$,\begin{align*}
        \mathcal{P}_0\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}\ge \tau \right)+\mathcal{P}_1\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}<\tau \right)\le 0.05.
    \end{align*}

    If $p=n^{-o(1)}$, then for any constant $\epsilon>0$, when $N_{\mathsf{e}} = o\left( \frac{\log n}{\max\left( \log\log n,-\log\rho \right)} \right)$ and $N_{\mathsf{e}}\ge \frac{C_2(\epsilon)}{\rho^{2+\epsilon}}$ for some constant $C_2(\epsilon)$ depending on $\epsilon$,\begin{align*}
        \mathcal{P}_0\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}\ge \tau \right)+\mathcal{P}_1\left( \mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}<\tau \right)\le 0.05.
    \end{align*}

    Furthermore, $\mathcal{T}_{\mathcal{M}(N_{\mathsf{e}},d)}$ is  computable in time $O(n^{N_{\mathsf{e}}+1+o(1)})$.

For any \emph{$C$-admissible} motif family $\mathcal{M}$, there exist $\tau,\omega_{\mathsf{M}}\in \mathbb{R}$ such that,
    \begin{align*}
        \mathcal{P}_0\left( \mathcal{T}_{\mathcal{M}}\ge\tau \right)+\mathcal{P}_1(\mathcal{T}_{\mathcal{M}}< \tau)\le 0.05.
    \end{align*}
